import type { ImportedBookmarkItem } from "../types";
import { isImportableHttpUrl } from "../utils";

function decodeHtmlEntities(input: string): string {
  return input
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_m, dec) => String.fromCharCode(Number(dec)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_m, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&amp;/g, "&");
}

/**
 * Parses Netscape Bookmark HTML exports (generated by Chrome, Safari, Firefox, Edge, Arc, etc.).
 */
export function parseNetscapeBookmarksHtml(htmlContent: string): ImportedBookmarkItem[] {
  const items: ImportedBookmarkItem[] = [];
  const anchorRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
  let match: RegExpExecArray | null;

  while ((match = anchorRe.exec(htmlContent)) !== null) {
    const attrs = match[1];
    const innerText = decodeHtmlEntities(match[2].replace(/<[^>]+>/g, "")).trim();

    const hrefMatch = /\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs);
    const rawUrl = decodeHtmlEntities(hrefMatch?.[1] ?? hrefMatch?.[2] ?? hrefMatch?.[3] ?? "").trim();
    if (!isImportableHttpUrl(rawUrl)) continue;

    const addDateMatch = /\badd_date\s*=\s*(?:"(\d+)"|'(\d+)'|(\d+))/i.exec(attrs);
    const rawDate = Number(addDateMatch?.[1] ?? addDateMatch?.[2] ?? addDateMatch?.[3] ?? 0);
    const createdAt = rawDate > 0 ? (rawDate > 1e12 ? rawDate : rawDate * 1000) : undefined;

    items.push({
      title: innerText || rawUrl,
      url: rawUrl,
      createdAt
    });
  }

  return items;
}
